  "summary": "The code contains 5 identified issues ranging from high-severity XSS vulnerabilities to maintainability concerns like hardcoded ports and lack of modularity. Overall code health is poor due to the lack of input sanitization and production-ready configuration. The fixed code addresses these by implementing escaping, environment variables, and basic modular structure.",
  "fixed_code": "/**\n * Express server providing greeting and status endpoints.\n */\nconst express = require(\"express\");\nconst rateLimit = require(\"express-rate-limit\");\n\nconst app = express();\nconst PORT = process.env.PORT || 3000;\n\nconst limiter = rateLimit({\n  windowMs: 15 * 60 * 1000,\n  max: 100\n});\n\napp.use(limiter);\n\nconst escapeHtml = (unsafe) => {\n  return String(unsafe).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');\n};\n\napp.get(\"/hello\", (req, res) => {\n  const rawName = typeof req.query.name === 'string' ? req.query.name : 'friend';\n  const name = escapeHtml(rawName);\n  res.type(\"html\").send(`<main><h1>Hello, ${name}!</h1></main>`);\n});\n\napp.get(\"/status\", (req, res) => {\n  res.json({ ok: true });\n});\n\napp.listen(PORT, () => console.log(`Server running on port ${PORT}`));"
}
